          "flashcards": [
            {
              "front": "Core principle of General Register Organization?",
              "back": "Establishes deterministic dataflow, memory hierarchy trade-offs, and micro-architectural timing constraints."
            },
            {
              "front": "Distinction between RISC and CISC?",
              "back": "RISC emphasizes simple, single-cycle fixed-length instructions with load/store architecture. CISC provides complex, variable-length instructions with extensive addressing modes executing over multiple cycles."
            },
            {
              "front": "What is Cache Coherence?",
              "back": "The consistency problem that arises when multiple processors maintain local private cache copies of shared main memory data, resolved via Snooping (Write-Invalidate/Update) or Directory-based protocols."
            },
            {
              "front": "What is Flynn's Bottleneck in SIMD?",
              "back": "Control divergence: when conditional branches execute, processors that do not take the branch must idle while the other group completes execution."
            }
          ]
